import React, { useEffect, useState } from 'react';
import moment from 'moment';
import { Button, Table, Tooltip, Tag, Dropdown, message } from 'antd';
import {
  ExportOutlined,
  TrophyOutlined,
  InboxOutlined,
  RiseOutlined,
  FundProjectionScreenOutlined,
  ArrowUpOutlined,
  ArrowDownOutlined,
  SearchOutlined,
  DownOutlined,
  FileExcelOutlined,
  FileTextOutlined,
} from '@ant-design/icons';
import { useDispatch, useSelector } from 'react-redux';
import { getProductRanking, exportCatalogDetails } from '../../redux/organicPerformance/actionCreator';

function ProductRanking() {
  const dispatch = useDispatch();
  const [searchText, setSearchText] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [exportLoading, setExportLoading] = useState(false);

  const [pagination, setPagination] = React.useState({
    current: 1,
    pageSize: 10,
  });

  // const [selectedRowKeys, setSelectedRowKeys] = React.useState([]);

  const { loading, productRankingData, dateRange } = useSelector((state) => ({
    loading: state?.OrganicPerformance?.loading,
    productRankingData: state?.OrganicPerformance?.productRankingData,
    dateRange: state?.dashboard?.dateRange,
  }));

  const [isDateFilterActive, setIsDateFilterActive] = useState(false);
  const isInitialMount = React.useRef(true);
  const initialDateRangeRef = React.useRef(dateRange);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchText);
    }, 500);

    return () => clearTimeout(timer);
  }, [searchText]);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      initialDateRangeRef.current = dateRange;
      return;
    }

    if (
      dateRange?.isUserSelected ||
      (dateRange && dateRange !== initialDateRangeRef.current && !dateRange?.isInitial)
    ) {
      setIsDateFilterActive(true);
      setPagination((prev) => (prev.current === 1 ? prev : { ...prev, current: 1 }));
    } else if (dateRange?.isInitial && !dateRange?.isUserSelected) {
      setIsDateFilterActive(false);
      setPagination((prev) => (prev.current === 1 ? prev : { ...prev, current: 1 }));
    }
  }, [dateRange]);

  useEffect(() => {
    const payload = { search: debouncedSearch };
    if (isDateFilterActive && dateRange?.fromDate) {
      payload.fromDate = dateRange.fromDate;
      payload.toDate = dateRange.endDate || dateRange.toDate;
    }
    dispatch(getProductRanking(pagination.current, pagination.pageSize, payload));
  }, [dispatch, pagination.current, pagination.pageSize, debouncedSearch, isDateFilterActive, dateRange]);

  const handleExport = async (format = 'xlsx') => {
    setExportLoading(true);
    try {
      const exportPayload = {
        search: debouncedSearch,
      };
      if (isDateFilterActive && dateRange?.fromDate) {
        exportPayload.fromDate = dateRange.fromDate;
        exportPayload.toDate = dateRange.endDate || dateRange.toDate;
      }
      const res = await dispatch(exportCatalogDetails(exportPayload, format));
      if (res?.status) {
        message.success('Export report generated successfully!');
      } else {
        message.error(res?.message || 'Failed to export product ranking data');
      }
    } catch (err) {
      console.error(err);
      message.error('Failed to export product ranking data');
    } finally {
      setExportLoading(false);
    }
  };

  const exportMenuItems = [
    {
      key: 'xlsx',
      label: 'Excel (.xlsx)',
      icon: <FileExcelOutlined style={{ color: '#10b981' }} />,
      onClick: () => handleExport('xlsx'),
    },
    {
      key: 'csv',
      label: 'CSV (.csv)',
      icon: <FileTextOutlined style={{ color: '#3b82f6' }} />,
      onClick: () => handleExport('csv'),
    },
  ];

  const dataSource =
    productRankingData?.data?.map((item) => ({
      key: item.id,
      image: item.image_url,

      asin: item.asin,
      brand: item.brand,
      itemName: item.item_name,
      saleRank: item.sales_rank,
      saleRankCategry: item.sales_rank_category,
      dispalyGroupRank: item.display_group_rank,
      groupRankTitle: item.display_group_rank_title,
      productSiteLaunchDate: item.product_site_launch_date,
    })) || [];

  const columns = [
    {
      title: 'Image',
      dataIndex: 'image',
      align: 'center',
      width: 50,
      render: (v) => (
        <img
          src={v}
          alt="product"
          className="w-[40px] h-[40px] object-contain mx-auto rounded-lg border p-1 bg-white"
        />
      ),
    },

    {
      title: 'ASIN',
      dataIndex: 'asin',
      align: 'center',
      width: 70,
      sorter: (a, b) => a.asin - b.asin,
      render: (v) => <span className="font-semibold text-[#2563eb] text-[11px]">{v || '-'}</span>,
    },

    {
      title: 'Brand',
      dataIndex: 'brand',
      align: 'center',
      width: 70,
      sorter: (a, b) => a.brand - b.brand,
      render: (v) => <span className="font-medium text-[#111827] text-[11px]">{v || '-'}</span>,
    },

    {
      title: 'Product Name',
      dataIndex: 'itemName',
      align: 'center',
      width: 70,
      sorter: (a, b) => a.itemName - b.itemName,
      render: (v) => (
        <Tooltip title={v} color="black" overlayInnerStyle={{ color: '#fff' }}>
          <span
            className="block truncate font-medium cursor-pointer text-[#111827] mx-auto text-[11px]"
            style={{ maxWidth: '200px' }}
          >
            {v || '-'}
          </span>
        </Tooltip>
      ),
    },

    {
      title: 'Product Category Rank',
      dataIndex: 'saleRank',
      align: 'center',
      width: 70,
      ellipsis: true,
      // sorter: (a, b) => {
      //   const rankA = Number(a.saleRank) || 0;
      //   const rankB = Number(b.saleRank) || 0;

      //   return rankA - rankB;
      // },
      sorter: (a, b) => a.saleRank - b.saleRank,
      render: (v) => <span className="text-[#374151] text-[11px]">{v || '-'}</span>,
    },

    {
      title: 'Master Category Rank',
      dataIndex: 'dispalyGroupRank',
      align: 'center',
      width: 70,
      ellipsis: true,
      sorter: (a, b) => a.dispalyGroupRank - b.dispalyGroupRank,
      render: (v) => <Tag className="!px-3 !py-[3px] !rounded-full text-[11px]">{v || '-'}</Tag>,
    },

    {
      title: 'Product Category',
      dataIndex: 'saleRankCategry',
      align: 'center',
      width: 70,
      ellipsis: true,
      render: (v) => (
        <Tooltip title={v} color="black" overlayInnerStyle={{ color: '#fff' }}>
          <span
            className="block truncate cursor-pointer text-[#374151] mx-auto text-[11px]"
            style={{
              maxWidth: '180px',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
            }}
          >
            {v || '-'}
          </span>
        </Tooltip>
      ),
    },
    {
      title: 'Master Category',
      dataIndex: 'groupRankTitle',
      align: 'center',
      width: 70,
      ellipsis: true,
      render: (v) => <Tag className="!px-3 !py-[3px] !rounded-full text-[11px]">{v || '-'}</Tag>,
    },
    {
      title: 'Product Launch Date',
      dataIndex: 'productSiteLaunchDate',
      align: 'center',
      width: 70,
      ellipsis: true,
      sorter: (a, b) => {
        const dateA = a.productSiteLaunchDate ? new Date(a.productSiteLaunchDate).getTime() : 0;
        const dateB = b.productSiteLaunchDate ? new Date(b.productSiteLaunchDate).getTime() : 0;
        return dateA - dateB;
      },
      render: (v) => {
        if (!v) return <span className="text-[#9ca3af] text-[11px]">-</span>;
        const m = moment(v);
        const formatted = m.isValid() ? m.format('DD/MM/YYYY') : String(v).slice(0, 10);
        return <span className="text-[#374151] text-[11px]">{formatted}</span>;
      },
    },
  ];

  const summary = productRankingData?.summary || {};

  const stats = [
    {
      title: 'Total Products Tracked',
      value:
        summary?.total_products_tracked !== undefined
          ? Number(summary.total_products_tracked).toLocaleString()
          : productRankingData?.count !== undefined
          ? Number(productRankingData.count).toLocaleString()
          : '156',
      change: '—',
      trend: 'neutral',
      icon: <InboxOutlined className="text-[#7c3aed]" />,
      bg: 'bg-[#f3e8ff]',
    },

    {
      title: 'In Top 100 (Product Category Rank)',
      value: summary?.in_top_100 !== undefined ? Number(summary.in_top_100).toLocaleString() : '28',
      change: '12%',
      trend: 'up',
      icon: <TrophyOutlined className="text-[#16a34a]" />,
      bg: 'bg-[#dcfce7]',
    },

    {
      title: 'Avg. Product Category Rank',
      value:
        summary?.avg_product_category_rank !== undefined
          ? Number(summary.avg_product_category_rank).toLocaleString()
          : '856',
      change: '8%',
      trend: 'down',
      icon: <RiseOutlined className="text-[#f59e0b]" />,
      bg: 'bg-[#fef3c7]',
    },

    {
      title: 'Avg. Master Category Rank',
      value:
        summary?.avg_master_category_rank !== undefined
          ? Number(summary.avg_master_category_rank).toLocaleString()
          : '45,362',
      change: '5%',
      trend: 'down',
      icon: <FundProjectionScreenOutlined className="text-[#2563eb]" />,
      bg: 'bg-[#dbeafe]',
    },

    {
      title: 'Products Improved',
      value: summary?.products_improved !== undefined ? Number(summary.products_improved).toLocaleString() : '64',
      change: '18%',
      trend: 'up',
      icon: <ArrowUpOutlined className="text-[#16a34a]" />,
      bg: 'bg-[#dcfce7]',
    },

    {
      title: 'Products Declined',
      value: summary?.products_declined !== undefined ? Number(summary.products_declined).toLocaleString() : '34',
      change: '6%',
      trend: 'up',
      icon: <ArrowDownOutlined className="text-[#ef4444]" />,
      bg: 'bg-[#fee2e2]',
    },
  ];

  return (
    <div className="p-3 px-4 bg-[#f8fafc] min-h-screen">
      {/* HEADER */}

      <div className="flex items-center justify-between mb-3 flex-wrap gap-3">
        <div>
          <h1 className="text-[20px] font-bold mb-0">Product Ranking</h1>

          <p className="text-[13px] text-[#6b7280]">
            Track your product performance and marketplace level ranking data.
          </p>
        </div>

        <div className="flex items-center gap-3">
          {/* ACTIVE DATE FILTER TAG */}
          {isDateFilterActive && dateRange?.fromDate && (
            <Tag
              closable
              onClose={() => {
                setIsDateFilterActive(false);
                setPagination((prev) => (prev.current === 1 ? prev : { ...prev, current: 1 }));
              }}
              color="blue"
              className="!h-[30px] !px-2.5 !py-0 !rounded-xl !text-[12px] flex items-center gap-1 cursor-pointer font-medium"
            >
              {`Launch Date: ${moment(dateRange.fromDate).format('DD/MM/YYYY')} - ${moment(
                dateRange.endDate || dateRange.toDate,
              ).format('DD/MM/YYYY')}`}
            </Tag>
          )}

          {/* SEARCH INPUT */}
          <div className="relative w-[260px]">
            <input
              type="text"
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              placeholder="Search products, ASIN..."
              className="w-full h-[30px] rounded-xl border bg-white pl-9 pr-3 text-[13px] text-[#111827] outline-none shadow-sm transition-all duration-200 focus:border-[#dbe1e8]"
            />
            <SearchOutlined className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9ca3af] text-[14px]" />
          </div>

          {/* EXPORT DROPDOWN */}
          <Dropdown menu={{ items: exportMenuItems }} placement="bottomRight" trigger={['click']}>
            <Button
              type="primary"
              loading={exportLoading}
              icon={<ExportOutlined />}
              className="!h-[30px] text-[13px] !px-3 !rounded-xl !bg-[#16a34a] !border-[#16a34a] !font-semibold !flex !items-center !justify-center gap-1 cursor-pointer"
            >
              Export <DownOutlined className="text-[10px]" />
            </Button>
          </Dropdown>
        </div>
      </div>

      {/* STATS */}

      <div className="grid grid-cols-6 gap-2 xl:grid-cols-3 md:grid-cols-2 sm:grid-cols-1 mb-2">
        {stats.map((item) => (
          <div key={item.title} className="bg-white border border-[#edf0f2] rounded-xl px-3 py-3 min-h-[92px]">
            {/* TOP ROW */}
            <div className="flex items-start justify-between mb-3">
              <p className="text-[11px] font-medium text-[#6b7280] leading-[14px]">{item.title}</p>

              <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${item.bg}`}>
                {item.icon}
              </div>
            </div>

            {/* VALUE */}
            <div className="text-[20px] font-bold text-[#111827] leading-none mb-2">{item.value}</div>

            {/* CHANGE */}
            <div
              className={`flex items-center gap-1 text-[11px] font-medium ${
                item.trend === 'up' ? 'text-[#16a34a]' : item.trend === 'down' ? 'text-[#ef4444]' : 'text-[#6b7280]'
              }`}
            >
              {item.trend === 'up' && <span>↑</span>}
              {item.trend === 'down' && <span>↓</span>}

              <span>{item.change}</span>

              <span className="text-[#6b7280]">vs last 30 days</span>
            </div>
          </div>
        ))}
      </div>

      {/* TABLE CARD */}

      <div className="bg-white border border-[#edf0f2] rounded-xl overflow-hidden">
        <div className="px-3 py-2 border-b border-[#edf0f2]">
          <h2 className="font-semibold text-[15px] text-[#111827] mb-0">Product Ranking Overview</h2>
        </div>

        <div className="p-3">
          <Table
            columns={columns}
            dataSource={dataSource}
            loading={loading}
            showSorterTooltip={false}
            tableLayout="fixed"
            pagination={{
              current: pagination.current,
              pageSize: pagination.pageSize,
              total: productRankingData?.count || 0,
              showSizeChanger: true,
              pageSizeOptions: ['10', '20', '50', '100'],
              showTotal: (total, range) => `${range[0]}-${range[1]} of ${total}`,
            }}
            onChange={(pag) => {
              setPagination({
                current: pag.current,
                pageSize: pag.pageSize,
              });
            }}
            scroll={{ x: 800 }}
            size="middle"
            bordered={false}
            className="
    [&_.ant-table-thead>tr>th]:!text-[12px]
    [&_.ant-table-thead>tr>th]:!font-semibold
    [&_.ant-table-tbody>tr>td]:!text-[12px]
    [&_.ant-table-cell]:!px-2
    [&_.ant-table-cell]:!py-2
  "
          />
        </div>
      </div>
    </div>
  );
}

export default ProductRanking;
